const input = $input.first().json;
let user_id, message, channel, phone_or_chat_id;
if (input.data && input.data.body !== undefined) {
  const from = input.data.from || '';
  user_id = 'wa_' + from.replace('@s.whatsapp.net','').replace('@c.us','');
  message = (input.data.body || '').trim();
  channel = 'whatsapp';
  phone_or_chat_id = from;
} else if (input.message) {
  user_id = 'tg_' + String(input.message.from.id);
  message = (input.message.text || '').trim();
  channel = 'telegram';
  phone_or_chat_id = String(input.message.chat.id);
} else {
  return [];
}
return [{ json: { user_id, message, channel, phone_or_chat_id, timestamp: new Date().toISOString() } }];

const input = $input.all();
const normalized = $('Normalize Input').first().json;
if (input.length > 0 && input[0].json) {
  const first = input[0].json;
  if (first && first.user_id) return [{ json: first }];
  if (Array.isArray(first) && first.length > 0) return [{ json: first[0] }];
}
return [{ json: { user_id: normalized.user_id, not_found: true } }];

const profil = $input.first().json;
const normalized = $('Normalize Input').first().json;
const message = (normalized.message || '').trim();
const channel = normalized.channel;
const phone_or_chat_id = normalized.phone_or_chat_id;
const user_id = normalized.user_id;

const sanitize = (str) => (str || '').replace(/["'`{}<>\\]/g, ' ').trim().slice(0, 500);

const extractPrenom = (msg) => {
  const patterns = [
    /je\s+(?:m['\u2019]appelle|me\s+pr[e\u00e9]nomme|suis)\s+([A-Z\u00c0-\u0178a-z\u00e0-\u00ff\-]+)/i,
    /mon\s+pr[e\u00e9]nom\s+(?:est|c['\u2019]est)\s+([A-Z\u00c0-\u0178a-z\u00e0-\u00ff\-]+)/i,
    /(?:^|\s)c['\u2019]est\s+([A-Z\u00c0-\u0178a-z\u00e0-\u00ff\-]+)$/i,
    /^([A-Z\u00c0-\u0178a-z\u00e0-\u00ff\-]+)$/
  ];
  for (const p of patterns) {
    const m = msg.match(p);
    if (m && m[1].length > 1) return m[1].charAt(0).toUpperCase() + m[1].slice(1).toLowerCase();
  }
  const words = msg.trim().split(/\s+/);
  if (words.length === 1) {
    const w = words[0].replace(/[^A-Z\u00c0-\u0178a-z\u00e0-\u00ff\-]/gi, '');
    if (w.length > 1) return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
  }
  return '';
};

const MSG = {
  "0": "\ud83c\udf3f Bonjour,\n\nJe suis *Tinga*, ton coach IA de d\u00e9veloppement personnel.\n\nJe suis une intelligence artificielle \u2014 je pr\u00e9f\u00e8re te le dire clairement d\u00e8s le d\u00e9part. Mais je ne suis pas n'importe quel outil.\n\nJe suis construit sur les travaux d'Elijah Parfait ONDO OYONO, coach praticien-chercheur et consultant bas\u00e9 \u00e0 Libreville, auteur de \"Le coaching \u00e0 l'africaine \u2014 entre syst\u00e8mes symboliques et d\u00e9veloppement social.\"\n\nC'est sur cette base que je travaille. Pas des formules import\u00e9es. Pas des promesses vides. Une m\u00e9thode ancr\u00e9e dans notre r\u00e9alit\u00e9.\n\nCe que je fais : t'aider \u00e0 voir plus clair, \u00e0 d\u00e9finir ce que tu veux vraiment, et \u00e0 avancer pas \u00e0 pas.\n\nCe que je ne fais pas : te donner des formules magiques, pr\u00e9tendre tout r\u00e9soudre, ou me substituer \u00e0 un professionnel de sant\u00e9 si tu en as besoin.\n\nTout ce que tu partages ici reste entre nous.\n\nOn commence ? Dis-moi ton pr\u00e9nom. \ud83d\udc4b",
  "0_retry": "Je n'ai pas bien saisi ton pr\u00e9nom. Peux-tu me le dire simplement \u2014 juste ton pr\u00e9nom ? \ud83d\ude0a",
  "1": "{PRENOM}, bienvenue.\n\nAvant qu'on commence, je veux qu'on soit honn\u00eates l'un envers l'autre.\n\nJe suis un coach IA \u2014 pas un m\u00e9decin, pas un th\u00e9rapeute. Il y a des situations que je peux t'accompagner \u00e0 traverser, et d'autres qui n\u00e9cessitent un autre type de soutien.\n\nPour qu'on parte du bon pied : dis-moi comment tu vas en ce moment \u2014 vraiment. Pas la version polie. Ce qui se passe pour toi.",
  "2": "Je t'entends, {PRENOM}.\n\nPeux-tu m'en dire un peu plus ? Qu'est-ce qui se passe concr\u00e8tement dans ta vie en ce moment ?",
  "3": "Pour t'accompagner avec justesse, j'ai besoin de comprendre ton contexte \u2014 pas pour te juger, pour te voir tel(le) que tu es.\n\nDis-moi : qu'est-ce que tu fais dans la vie en ce moment ?\nTon activit\u00e9, ton travail, ta situation \u2014 comme tu veux le d\u00e9crire.",
  "4": "{PRENOM}, maintenant dis-moi \u2014 et prends le temps qu'il faut :\n\nQu'est-ce qui t'a amen\u00e9(e) ici aujourd'hui ?\n\nPas la version courte. La vraie. Ce que tu portes, ce qui te manque, ce que tu veux atteindre ou ce qui te bloque.\n\nJe t'\u00e9coute.",
  "5": "Ce que tu partages est important, {PRENOM}.\n\nUne question que peu de coachs posent \u2014 mais que je consid\u00e8re essentielle :\n\nCe que tu veux changer ou construire, est-ce que \u00e7a te concerne uniquement toi ? Ou est-ce qu'il y a des personnes autour de toi \u2014 famille, proches, communaut\u00e9 \u2014 qui sont touch\u00e9es par ce changement, d'une mani\u00e8re ou d'une autre ?\n\nDans notre r\u00e9alit\u00e9, on n'avance jamais vraiment seul(e). Un coaching qui ignore \u00e7a ne va pas loin.",
  "6": "Est-ce que tu as d\u00e9j\u00e0 essay\u00e9 de changer cette situation ou d'avancer vers cet objectif ?\n\nSi oui \u2014 qu'est-ce que tu as tent\u00e9 ? Et pourquoi \u00e7a n'a pas suffi, selon toi ?\n\nSi non \u2014 qu'est-ce qui t'a retenu jusqu'ici ?",
  "7": "Derni\u00e8re question avant qu'on construise ton programme.\n\nImagine que dans quelques mois, tu regardes en arri\u00e8re et tu te dis : \"ce coaching a vraiment chang\u00e9 quelque chose.\"\n\nQu'est-ce qui a chang\u00e9 ? Dans ta vie, ton quotidien, tes relations \u2014 pas juste dans ta t\u00eate.\n\nD\u00e9cris-moi \u00e7a. M\u00eame si c'est flou. Surtout si c'est flou."
};
const fmt = (key, prenom) => (MSG[key] || '').replace(/\{PRENOM\}/g, prenom || '');

if (profil.coaching_phase === 'ORIENTE') {
  return [{ json: {
    user_id, channel, phone_or_chat_id,
    onboarding_step: profil.onboarding_step || 1,
    coaching_phase: 'ORIENTE',
    prenom: profil.prenom || '',
    response: `Tinga est toujours l\u00e0 quand tu te sens pr\u00eat(e)${profil.prenom ? ', ' + profil.prenom : ''}. \ud83c\udf3f`,
    needs_triage: false, needs_llm: false, needs_coaching_llm: false
  }}];
}

const step = Number(profil.onboarding_step) || 0;
const prenom = profil.prenom || '';

if (profil.not_found) {
  return [{ json: {
    user_id, channel, phone_or_chat_id,
    onboarding_step: 0, coaching_phase: 'ONBOARDING',
    is_new: true, response: MSG['0'],
    needs_triage: false, needs_llm: false, needs_coaching_llm: false
  }}];
}

if (step === 0) {
  const nom = extractPrenom(message);
  if (!nom) {
    return [{ json: {
      ...profil, user_id, channel, phone_or_chat_id,
      onboarding_step: 0,
      response: MSG['0_retry'],
      needs_triage: false, needs_llm: false, needs_coaching_llm: false
    }}];
  }
  return [{ json: {
    ...profil, user_id, channel, phone_or_chat_id,
    onboarding_step: 1, prenom: nom,
    response: fmt('1', nom),
    needs_triage: false, needs_llm: false, needs_coaching_llm: false
  }}];
}

if (step === 1) {
  return [{ json: {
    ...profil, user_id, channel, phone_or_chat_id,
    onboarding_step: 2, etat_initial: sanitize(message),
    response: fmt('2', prenom),
    needs_triage: false, needs_llm: false, needs_coaching_llm: false
  }}];
}

if (step === 2) {
  return [{ json: {
    ...profil, user_id, channel, phone_or_chat_id,
    onboarding_step: 3, situation_initiale: sanitize(message),
    response: null,
    needs_triage: true, needs_llm: false, needs_coaching_llm: false
  }}];
}

if (step === 3) {
  return [{ json: {
    ...profil, user_id, channel, phone_or_chat_id,
    onboarding_step: 4, response: MSG['3'],
    needs_triage: false, needs_llm: false, needs_coaching_llm: false
  }}];
}

if (step === 4) {
  return [{ json: {
    ...profil, user_id, channel, phone_or_chat_id,
    onboarding_step: 5, situation: sanitize(message),
    response: fmt('4', prenom),
    needs_triage: false, needs_llm: false, needs_coaching_llm: false
  }}];
}

if (step === 5) {
  return [{ json: {
    ...profil, user_id, channel, phone_or_chat_id,
    onboarding_step: 6, defi_exprime: sanitize(message),
    response: fmt('5', prenom),
    needs_triage: false, needs_llm: false, needs_coaching_llm: false
  }}];
}

if (step === 6) {
  return [{ json: {
    ...profil, user_id, channel, phone_or_chat_id,
    onboarding_step: 7, ecosysteme: sanitize(message),
    response: MSG['6'],
    needs_triage: false, needs_llm: false, needs_coaching_llm: false
  }}];
}

if (step === 7) {
  return [{ json: {
    ...profil, user_id, channel, phone_or_chat_id,
    onboarding_step: 8, deja_essaye: sanitize(message),
    response: MSG['7'],
    needs_triage: false, needs_llm: false, needs_coaching_llm: false
  }}];
}

if (step === 8) {
  return [{ json: {
    ...profil, user_id, channel, phone_or_chat_id,
    onboarding_step: 9, vision_reussite: sanitize(message),
    response: null,
    needs_triage: false, needs_llm: true, needs_coaching_llm: false
  }}];
}

if (step === 9) {
  const msgLow = message.toLowerCase();
  const motsCles = [
    'oui','ok','d\'accord','parfait','convient','valid\u00e9','ok\u00e9','\u00e7a me va','c\'est bon',
    'super','g\u00e9nial','yes','allons-y','go','top','bien','bonne id\u00e9e','j\'accepte',
    'je valide','on y va','nickel','let\'s go','c\'est parfait','\u00e7a convient','correct'
  ];
  const valide = motsCles.some(k => msgLow.includes(k));
  if (valide) {
    return [{ json: {
      ...profil, user_id, channel, phone_or_chat_id,
      onboarding_step: 10, coaching_phase: 'PROGRAMME_VALIDE',
      response: `Parfait, ${prenom} ! Ton programme est lanc\u00e9. \ud83c\udf3f\n\nOn commence d\u00e8s maintenant. Je reviens vers toi avec la premi\u00e8re s\u00e9ance.`,
      needs_triage: false, needs_llm: false, needs_coaching_llm: false
    }}];
  }
  return [{ json: {
    ...profil, user_id, channel, phone_or_chat_id,
    onboarding_step: 9,
    response: `Je t'entends, ${prenom}. Dis-moi ce que tu voudrais ajuster \u2014 je l'adapte.`,
    needs_triage: false, needs_llm: false, needs_coaching_llm: false
  }}];
}

// Step 10+ : coaching actif — route vers le LLM de coaching
return [{ json: {
  ...profil, user_id, channel, phone_or_chat_id,
  onboarding_step: step,
  coaching_phase: profil.coaching_phase || 'PROGRAMME_VALIDE',
  message_actuel: message,
  response: null,
  needs_triage: false, needs_llm: false, needs_coaching_llm: true
}}];

const d = $('Check User & Route').first().json;
const input = $input.all();
let programme = {};
if (input.length > 0 && input[0].json) {
  const first = input[0].json;
  if (first && first.user_id) programme = first;
  else if (Array.isArray(first) && first.length > 0) programme = first[0];
}
return [{ json: { ...d, programme } }];

const d = $input.first().json;
const prenom = d.prenom || '';
const programme = d.programme || {};

const sanitize = (str) => (str || '').replace(/["'`{}<>\]/g, ' ').trim().slice(0, 500);

const themes = Array.isArray(programme.themes)
  ? programme.themes.map(t => `• Séance ${t.numero} — ${t.theme}: ${t.objectif}`).join('
')
  : 'Programme en cours';

const prompt = `Tu es Tinga, coach IA ancré dans la méthodologie du coaching à l'africaine d'Elijah Parfait ONDO OYONO.

Tu accompagnes ${prenom} dans son programme de coaching.

PROGRAMME DE ${prenom.toUpperCase()} :
Objectif global : ${programme.objectif_global || 'non précisé'}
Durée : ${programme.duree_estimee || '6 semaines'}
Critères de réussite : ${programme.criteres_evaluation || 'non précisé'}

THÈMES DU PROGRAMME :
${themes}

CONTEXTE PERSONNEL :
- Situation : "${sanitize(d.situation)}"
- Défi principal : "${sanitize(d.defi_exprime)}"
- Ce qui a déjà été tenté : "${sanitize(d.deja_essaye)}"
- Vision de réussite : "${sanitize(d.vision_reussite)}"

MESSAGE ACTUEL DE ${prenom} : "${sanitize(d.message_actuel)}"

Réponds en coach bienveillant et direct. 2-4 paragraphes maximum. Pose UNE seule question de suivi si nécessaire. Ton chaleureux, ancré dans la réalité africaine. Ne réponds pas avec une liste — parle comme un coach.`;

return [{ json: { ...d, coaching_prompt: prompt } }];

const text = ($input.first().json.text || '').trim();
const d = $('Check User & Route').first().json;
if (!text) {
  return [{ json: {
    ...d,
    response: `Je suis l\u00e0, ${d.prenom || ''}. Qu'est-ce qui se passe pour toi aujourd'hui ?`
  }}];
}
return [{ json: { ...d, response: text } }];

const d = $('Check User & Route').first().json;
const prenom = d.prenom || '';

const sanitize = (str) => (str || '').replace(/["'`{}<>\]/g, ' ').trim().slice(0, 500);

const prompt = `Tu es Tinga, coach IA ancré dans la méthodologie du coaching à l'africaine.

Tu viens d'écouter ${prenom} pendant deux échanges :
- Ce qu'il/elle a dit sur comment il/elle va : "${sanitize(d.etat_initial)}"
- Ce qu'il/elle a dit sur sa situation concrète : "${sanitize(d.situation_initiale)}"

Ta mission : évaluer si cette personne peut bénéficier d'un coaching, ou si sa situation nécessite d'abord un accompagnement médical ou psychologique spécialisé.

IMPORTANT : Un coaching est POSSIBLE même si la personne traverse une période difficile, à condition que ce ne soit pas une crise aiguë (idées suicidaires actives, dépression sévère, psychose, addiction grave incontrôlée).

Réponds UNIQUEMENT en JSON sans markdown ni backticks :
{"peut_coacher": true ou false, "message_coach": "Si peut_coacher true : message chaleureux de 2-3 phrases qui reformule ce que tu as entendu et valide que vous pouvez travailler ensemble. NE pose PAS de question. Si peut_coacher false : message bienveillant de 2-3 phrases qui oriente vers un professionnel de santé sans être brutal, en laissant la porte ouverte."}

Règles strictes :
- Si doute, peut_coacher = true
- Ton chaleureux, jamais condescendant
- NE pose AUCUNE question dans message_coach
- AUCUN retour à la ligne dans les valeurs JSON`;

return [{ json: { ...d, triage_prompt: prompt } }];

const d = $('Check User & Route').first().json;

const MSG_ORIENTE = `{PRENOM}, merci de me faire confiance avec \u00e7a.\n\nCe que tu traverses m\u00e9rite un accompagnement que je ne peux pas t'offrir seul \u2014 et je pr\u00e9f\u00e8re \u00eatre honn\u00eate plut\u00f4t que de pr\u00e9tendre le contraire.\n\nCe dont tu as besoin, c'est d'un professionnel de sant\u00e9 mentale qualifi\u00e9 : un psychologue ou un psychiatre qui peut t'accompagner comme tu le m\u00e9rites.\n\n\ud83d\udc49 Si tu es au Gabon :\nCentre Hospitalier Universitaire de Libreville\nService de psychiatrie : +241 01 76 18 18\n\nSi jamais tu veux revenir ici pour travailler sur d'autres dimensions de ta vie quand tu te sens pr\u00eat(e), Tinga sera l\u00e0.\n\nPrens soin de toi. \ud83c\udf3f`;

try {
  const raw = ($input.first().json.text || '').replace(/```json|```/g, '').trim();
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('JSON triage introuvable');

  let cleaned = '';
  let inString = false, escaped = false;
  for (const char of jsonMatch[0]) {
    if (escaped) { cleaned += char; escaped = false; continue; }
    if (char === '\\') { cleaned += char; escaped = true; continue; }
    if (char === '"') inString = !inString;
    if (inString && (char === '\n' || char === '\r' || char === '\t')) { cleaned += ' '; continue; }
    cleaned += char;
  }

  const parsed = JSON.parse(cleaned);

  if (!parsed.peut_coacher) {
    return [{ json: {
      ...d, coaching_phase: 'ORIENTE',
      response: MSG_ORIENTE.replace(/\{PRENOM\}/g, d.prenom || ''),
      needs_triage: false, needs_llm: false, needs_coaching_llm: false
    }}];
  }

  return [{ json: {
    ...d, response: parsed.message_coach,
    coaching_phase: 'ONBOARDING',
    needs_triage: false, needs_llm: false, needs_coaching_llm: false
  }}];

} catch (e) {
  return [{ json: {
    ...d,
    response: `Je t'entends, ${d.prenom || ''}. Dis-moi un peu plus sur ton quotidien en ce moment.`,
    coaching_phase: 'ONBOARDING',
    needs_triage: false, needs_llm: false, needs_coaching_llm: false
  }}];
}

const d = $('Check User & Route').first().json;

const sanitize = (str) => (str || '').replace(/["'`{}<>\]/g, ' ').trim().slice(0, 500);

const prompt = `Tu es Tinga, coach IA construit sur la méthodologie de coaching à l'africaine d'Elijah Parfait ONDO OYONO.

Tu viens de terminer l'entretien préalable avec ${d.prenom}. Voici exactement ce qu'il/elle t'a dit :
- Comment il/elle allait : "${sanitize(d.etat_initial)}"
- Contexte de vie concret : "${sanitize(d.situation_initiale)}"
- Activité/travail actuel : "${sanitize(d.situation)}"
- Ce qui l'a amené(e) ici : "${sanitize(d.defi_exprime)}"
- Écosystème relationnel : "${sanitize(d.ecosysteme)}"
- Ce qui a déjà été tenté : "${sanitize(d.deja_essaye)}"
- Vision de réussite : "${sanitize(d.vision_reussite)}"

Produis UNIQUEMENT un JSON valide sans markdown, sans backticks, sans retour à la ligne dans les valeurs :
{"synthese": "2-3 phrases. Ce que tu as compris. UNIQUEMENT ce qu'il/elle a dit.", "objectif_global": "L'objectif en 1 phrase concrète.", "nb_seances": 6, "duree_estimee": "6 semaines", "criteres_evaluation": "Comment ${d.prenom} saura que ça a réussi.", "themes": [{"numero": 1, "theme": "Titre", "objectif": "Ce qu'on explore"}, {"numero": 2, "theme": "Titre", "objectif": "..."}, {"numero": 3, "theme": "Titre", "objectif": "..."}, {"numero": 4, "theme": "Titre", "objectif": "..."}, {"numero": 5, "theme": "Titre", "objectif": "..."}, {"numero": 6, "theme": "Bilan et projection", "objectif": "Évaluation et plan d'autonomie"}], "message_programme": "Message à envoyer à ${d.prenom} : synthèse de ce que tu as compris + programme proposé. Termine en demandant si ça lui convient."}

Règles STRICTES : zéro affirmation inventée, ton ancré dans la réalité africaine, AUCUN retour à la ligne dans les valeurs JSON.`;

return [{ json: { ...d, prompt } }];

try {
  const raw = ($input.first().json.text || '').replace(/```json|```/g, '').trim();
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('JSON synth\u00e8se introuvable');

  let cleaned = '';
  let inString = false, escaped = false;
  for (const char of jsonMatch[0]) {
    if (escaped) { cleaned += char; escaped = false; continue; }
    if (char === '\\') { cleaned += char; escaped = true; continue; }
    if (char === '"') inString = !inString;
    if (inString && (char === '\n' || char === '\r' || char === '\t')) { cleaned += ' '; continue; }
    cleaned += char;
  }

  const parsed = JSON.parse(cleaned);
  const d = $('Check User & Route').first().json;

  return [{ json: {
    ...d,
    response: parsed.message_programme,
    programme_data: {
      objectif_global: parsed.objectif_global,
      nb_seances: parsed.nb_seances,
      duree_estimee: parsed.duree_estimee,
      criteres_evaluation: parsed.criteres_evaluation,
      themes: parsed.themes
    }
  }}];

} catch (e) {
  const d = $('Check User & Route').first().json;
  return [{ json: {
    ...d,
    response: `${d.prenom || ''}, j'ai rencontr\u00e9 un probl\u00e8me technique lors de la cr\u00e9ation de ton programme. Peux-tu me renvoyer ta vision de r\u00e9ussite pour que je puisse r\u00e9essayer ?`,
    programme_data: null
  }}];
}
